import semver

def test_placebo_candidate():
    version = semver.VersionInfo.parse("1.2.3")

    # Test with a valid part and an invalid part
    try:
        result = version.replace(major=2, unknownkey="value")
    except TypeError as e:
        assert str(e) == "replace() got 1 unexpected keyword argument(s): unknownkey"
    else:
        assert False, "Expected a TypeError but got none"

    # Test with only valid parts
    new_version = version.replace(major=2, minor=4, patch=6)
    assert str(new_version) == "2.4.6"

